import { StudioProApi } from "@mendix/extensions-api";

import { Agent } from "../../types/agent";
import { KnowledgebaseTool, Tool } from "../../types/tool";
import { getCustomBlobDocumentById } from "../../utils/customBlobDocumentUtils";

export type KnowledgebaseToolField = keyof KnowledgebaseTool;

export const handleValidateKnowledgebaseTool = async (
    field: KnowledgebaseToolField,
    tool: KnowledgebaseTool,
    agent: Agent,
    studioPro: StudioProApi
): Promise<true | string> => {
    const existingKnowledgebaseTools: KnowledgebaseTool[] = agent.knowledgebaseTools;
    const existingTools: Tool[] = agent.tools;

    switch (field) {
        case "name":
            if (!tool.name || tool.name.trim() === "") {
                return "Knowledge base name cannot be empty.";
            }
            if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(tool.name)) {
                return "Knowledge base name must start with a letter or underscore and contain only letters, numbers, and underscores.";
            }
            if (tool.name.length > 64) {
                return "Knowledge base name cannot exceed 64 characters.";
            }
            if (
                existingKnowledgebaseTools &&
                existingKnowledgebaseTools.some((t) => t.name === tool.name && t.id !== tool.id)
            ) {
                return "Knowledge base name must be unique.";
            }
            if (existingTools && existingTools.some((t) => t.name === tool.name && t.id !== tool.id)) {
                return "This name must be unique. This name is already used for a tool of this agent, please choose a different name.";
            }
            break;

        case "description":
            if (!tool.description || tool.description.trim() === "") {
                return "Knowledge base description cannot be empty.";
            }
            if (tool.description.length > 4096) {
                return "Knowledge base description cannot exceed 4096 characters.";
            }
            break;

        case "document": {
            if (!tool.document || !tool.document.qualifiedName) {
                return "Knowledge base document must be selected.";
            }
            const document = await getCustomBlobDocumentById(studioPro, tool.document.documentId);
            if (!document) {
                return "Knowledge base document does not exist.";
            }
            break;
        }

        case "collectionIdentifier":
            if (!tool.collectionIdentifier || tool.collectionIdentifier.trim() === "") {
                return "Collection identifier cannot be empty.";
            }
            if (tool.collectionIdentifier.length > 200) {
                return "Collection identifier cannot exceed 200 characters.";
            }
            break;

        case "maxResults":
            if (tool.maxResults !== undefined && tool.maxResults !== null) {
                if (!Number.isInteger(tool.maxResults)) {
                    return "Max results must be a whole number.";
                }
                if (tool.maxResults < 1) {
                    return "Max results must be a valid number (1 or higher).";
                }
            }
            break;

        case "minSimilarity":
            console.log(tool);
            if (tool.minSimilarity !== undefined && tool.minSimilarity !== null) {
                if (!Number.isFinite(tool.minSimilarity)) {
                    return "Min similarity must be a valid number.";
                }
                if (tool.minSimilarity < 0 || tool.minSimilarity > 1) {
                    return "Min similarity must be between 0 and 1.";
                }
            }
            break;

        default:
            return true;
    }

    return true;
};
